// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(c));
        vm.prank(address(this));
        bool ok = false;
        try c.setOwner(newOwner) returns (bool result) { ok = result; } catch { ok = false; }
        assertTrue(!ok || c.owner() == newOwner);
    }
}
